INSERT INTO public.cwu_courses
  (title,slug,description,category,level,duration_minutes,instructor_id,price_inr,is_published,is_archived)
INSERT INTO public.cwu_lessons
  (course_id,title,description,content,sort_order,is_published)
VALUES
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-fundamentals'),'01 • Security Foundations','Learn the security goals, threat landscape, assets, vulnerabilities, risks, and common attack paths.','CIA triad, assets, threats, vulnerabilities, risk, controls, authentication and authorization. Practice identifying the security objective for common incidents.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-fundamentals'),'02 • Identity & Access Security','Understand how accounts are protected and why least privilege matters.','Authentication factors, MFA, password hygiene, authorization, RBAC, least privilege, account lifecycle and session security.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-fundamentals'),'03 • Network & Endpoint Defense','Build a baseline for protecting devices and networks.','Firewalls, segmentation, secure configuration, patching, endpoint protection, logging and safe remote access.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-fundamentals'),'04 • Secure Data & Applications','Learn practical ways to protect information throughout its lifecycle.','Data classification, encryption concepts, backups, input validation, secure secrets handling and secure development basics.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-fundamentals'),'05 • Incident Response Basics','Learn the first steps a defender takes when suspicious activity is detected.','Preparation, identification, containment, eradication, recovery and lessons learned; evidence preservation and communication.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='ethical-hacking-penetration-testing'),'01 • Ethical Hacking Methodology','Understand authorization, scope, rules of engagement and the penetration-testing lifecycle.','Pre-engagement, reconnaissance, enumeration, vulnerability validation, exploitation in scope, reporting and remediation.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='ethical-hacking-penetration-testing'),'02 • Reconnaissance & Enumeration','Learn how authorized testers collect information without crossing the agreed scope.','Passive and active reconnaissance, DNS concepts, service discovery, banners, asset inventory and evidence collection.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='ethical-hacking-penetration-testing'),'03 • Web & Network Testing','Study common weaknesses and safe validation techniques.','Authentication flaws, injection concepts, insecure configuration, exposed services, access control issues and controlled proof-of-concept testing.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='ethical-hacking-penetration-testing'),'04 • Exploitation & Privilege Concepts','Understand exploitation as a controlled validation activity.','Exploit chains, privilege boundaries, post-exploitation goals, persistence risks and why testing must stop at the agreed impact boundary.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='ethical-hacking-penetration-testing'),'05 • Reporting & Remediation','Turn technical findings into useful security improvements.','Severity, evidence, reproduction steps, business impact, remediation guidance, retesting and professional reporting.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='network-security-essentials'),'01 • Network Security Architecture','Learn how secure networks are structured.','Network zones, trust boundaries, segmentation, VLAN concepts, firewalls, gateways and defense in depth.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='network-security-essentials'),'02 • Secure Protocols & Services','Recognize secure and insecure network service patterns.','TLS, SSH, secure DNS concepts, VPNs, certificates, service exposure and protocol hardening.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='network-security-essentials'),'03 • Firewalls & Segmentation','Build rules that reduce unnecessary exposure.','Default-deny concepts, ingress/egress controls, allowlists, network segmentation and rule review.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='network-security-essentials'),'04 • Monitoring & Detection','Learn how network telemetry supports detection.','Logs, flow data, IDS/IPS concepts, alert triage, baselines, suspicious traffic patterns and retention.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='network-security-essentials'),'05 • Network Incident Response','Respond to suspicious network activity methodically.','Containment, isolation, packet/evidence preservation, investigation workflow, recovery and post-incident improvement.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='web-application-security'),'01 • Web Security Foundations','Understand the browser, server and API trust boundaries.','HTTP basics, cookies, sessions, authentication, authorization, same-origin concepts and common web threat categories.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='web-application-security'),'02 • Input Validation & Injection','Learn why untrusted input must be handled carefully.','Validation, encoding, parameterized queries, command injection concepts and safe testing of input boundaries.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='web-application-security'),'03 • Authentication & Access Control','Protect accounts and resources from unauthorized use.','Session management, MFA, password reset security, object-level authorization and privilege separation.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='web-application-security'),'04 • Client-Side & API Security','Secure modern web interfaces and APIs.','CORS concepts, browser storage risks, CSRF concepts, API authentication, rate limiting and secure error handling.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='web-application-security'),'05 • Secure Deployment & Testing','Integrate security into the web development lifecycle.','Security headers, dependency hygiene, secrets management, security testing, logging and remediation verification.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='python-for-cybersecurity'),'01 • Python Security Toolkit','Set up a safe Python workflow for defensive and authorized security tasks.','Data types, functions, files, exceptions, modules, virtual environments and responsible automation.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='python-for-cybersecurity'),'02 • Parsing Logs & Indicators','Use Python to turn security data into useful evidence.','Read CSV/text/JSON logs, normalize fields, search indicators, count events and generate simple reports.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='python-for-cybersecurity'),'03 • Network Automation Concepts','Automate repetitive defensive checks safely.','Sockets concepts, HTTP requests, DNS lookups, timeouts, validation, rate limits and error handling.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='python-for-cybersecurity'),'04 • Security Data & APIs','Work with structured security information.','JSON APIs, authentication tokens, pagination, input validation, secure storage of secrets and response validation.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='python-for-cybersecurity'),'05 • Build a Defensive Utility','Combine the skills into a small security automation project.','Design, validation, logging, safe defaults, testing, documentation and responsible deployment.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='linux-kali-linux-security'),'01 • Linux Security Foundations','Understand Linux users, permissions, processes and services.','Users, groups, file permissions, sudo, processes, services, package management and filesystem layout.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='linux-kali-linux-security'),'02 • Secure Shell & Administration','Administer Linux systems with safer operational habits.','SSH keys, configuration, least privilege, updates, service exposure, logs and account hardening.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='linux-kali-linux-security'),'03 • Kali Linux Workflow','Use Kali Linux responsibly as an authorized security-learning environment.','Tool categories, isolated labs, snapshots, documentation, scope control and safe evidence handling.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='linux-kali-linux-security'),'04 • System Monitoring & Hardening','Find and reduce unnecessary system exposure.','Processes, listening services, logs, firewall concepts, secure configuration and baseline comparison.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='linux-kali-linux-security'),'05 • Linux Incident Triage','Investigate a suspicious Linux host without destroying evidence.','Timeline building, authentication logs, process review, persistence indicators, containment and recovery.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='digital-forensics'),'01 • Forensic Principles','Learn how digital evidence is identified and preserved.','Evidence types, integrity, chain of custody, acquisition principles, legal/organizational scope and documentation.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='digital-forensics'),'02 • Disk & File System Evidence','Understand what investigators look for on storage media.','Partitions, filesystems, timestamps, deleted-file concepts, metadata and evidence hashing.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='digital-forensics'),'03 • Memory & Process Evidence','Learn the role of volatile evidence.','Processes, network connections, loaded modules, credentials exposure risks and why memory acquisition is time-sensitive.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='digital-forensics'),'04 • Browser & User Activity','Study common sources of user-activity evidence.','Browser history concepts, cookies, downloads, application artifacts, timestamps and careful interpretation.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='digital-forensics'),'05 • Forensic Reporting','Produce a clear and reproducible investigation report.','Methodology, evidence references, findings, limitations, timelines, conclusions and preservation of original artifacts.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cloud-security-fundamentals'),'01 • Cloud Security Model','Understand shared responsibility and cloud trust boundaries.','Provider versus customer responsibilities, identity, data, workloads, regions, logging and secure defaults.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cloud-security-fundamentals'),'02 • Cloud Identity & Access','Build strong cloud access controls.','IAM concepts, roles, least privilege, MFA, service identities, credential rotation and access reviews.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cloud-security-fundamentals'),'03 • Storage & Data Protection','Protect cloud data from accidental or unauthorized exposure.','Public/private access, encryption, key management concepts, backups, data classification and retention.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cloud-security-fundamentals'),'04 • Cloud Network Security','Reduce exposure around cloud workloads.','Virtual networks, security groups, network ACL concepts, private connectivity, segmentation and egress control.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cloud-security-fundamentals'),'05 • Cloud Monitoring & Response','Detect and respond to cloud security events.','Audit logs, alerts, configuration drift, incident containment, evidence collection and recovery.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='security-operations-threat-analysis'),'01 • SOC Foundations','Understand how a security operations team works.','SOC roles, telemetry, alert lifecycle, escalation, severity, playbooks and analyst documentation.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='security-operations-threat-analysis'),'02 • Threat Intelligence','Turn threat information into useful defensive context.','Indicators, tactics and techniques, intelligence lifecycle, confidence, enrichment and operational use.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='security-operations-threat-analysis'),'03 • Detection Engineering','Create detections that are useful and maintainable.','Log sources, detection logic, false positives, baselines, tuning, testing and versioned rules.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='security-operations-threat-analysis'),'04 • Incident Investigation','Investigate alerts from initial triage to containment.','Timeline, scoping, host/user context, evidence correlation, containment decisions and communication.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='security-operations-threat-analysis'),'05 • Threat Hunting & Metrics','Proactively search for suspicious behavior and measure program quality.','Hypothesis-driven hunting, queries, coverage, dwell time, false positives, response metrics and continuous improvement.',5,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-career-roadmap'),'01 • Choose Your Security Path','Map cybersecurity roles to skills and interests.','Blue team, red team, security engineering, cloud security, GRC, digital forensics and security research.',1,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-career-roadmap'),'02 • Build a Practical Portfolio','Create evidence of skills without exposing sensitive information.','Labs, write-ups, GitHub projects, responsible disclosures, documentation and portfolio structure.',2,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-career-roadmap'),'03 • Certifications & Learning Plan','Build a realistic study strategy.','Foundational knowledge, role-aligned certifications, projects, revision cycles and measurable learning goals.',3,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-career-roadmap'),'04 • Resume, LinkedIn & Interviews','Present technical skills clearly to employers.','ATS-friendly resume structure, project bullets, professional profile, interview preparation and technical storytelling.',4,true),
  ((SELECT id FROM public.cwu_courses WHERE slug='cybersecurity-career-roadmap'),'05 • First 90 Days in Cybersecurity','Plan the transition from learner to professional.','Continuous learning, workplace security, documentation, communication, mentorship, ethics and long-term growth.',5,true)
INSERT INTO public.cwu_quizzes
  (course_id,lesson_id,title,description,time_limit_seconds,pass_percent,version,is_published)
INSERT INTO public.cwu_quiz_questions
  (quiz_id,question_text,question_type,options,correct_answers,explanation,marks,sort_order)
VALUES
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cybersecurity-fundamentals' AND q.title='Final Assessment — Cybersecurity Fundamentals'),'Which security goal protects data from unauthorized disclosure?','single_choice','["Confidentiality","Availability","Redundancy","Compression"]'::jsonb,'["Confidentiality"]'::jsonb,'Confidentiality protects information from unauthorized disclosure.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cybersecurity-fundamentals' AND q.title='Final Assessment — Cybersecurity Fundamentals'),'What does least privilege mean?','single_choice','["Give users only the access they need","Give everyone administrator access","Disable all accounts","Share one account"]'::jsonb,'["Give users only the access they need"]'::jsonb,'Least privilege limits access to what is required for the task.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cybersecurity-fundamentals' AND q.title='Final Assessment — Cybersecurity Fundamentals'),'Which control helps require a second authentication factor?','single_choice','["MFA","DNS","NAT","FTP"]'::jsonb,'["MFA"]'::jsonb,'Multi-factor authentication requires more than one authentication factor.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cybersecurity-fundamentals' AND q.title='Final Assessment — Cybersecurity Fundamentals'),'What is a vulnerability?','single_choice','["A weakness that can be exploited","A backup copy","A security policy","A network cable"]'::jsonb,'["A weakness that can be exploited"]'::jsonb,'A vulnerability is a weakness that may be exploited to cause harm or gain access.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cybersecurity-fundamentals' AND q.title='Final Assessment — Cybersecurity Fundamentals'),'What is a key incident-response goal during containment?','single_choice','["Limit further impact","Delete all logs","Ignore evidence","Disable monitoring"]'::jsonb,'["Limit further impact"]'::jsonb,'Containment focuses on limiting spread and further impact while preserving investigation capability.',1,5),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='ethical-hacking-penetration-testing' AND q.title='Final Assessment — Ethical Hacking & Penetration Testing'),'What must exist before an authorized penetration test?','single_choice','["Permission and scope","A public exploit","A hidden account","No documentation"]'::jsonb,'["Permission and scope"]'::jsonb,'Authorized testing requires permission and a defined scope or rules of engagement.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='ethical-hacking-penetration-testing' AND q.title='Final Assessment — Ethical Hacking & Penetration Testing'),'Which phase focuses on collecting target information?','single_choice','["Reconnaissance","Recovery","Reporting only","Patching"]'::jsonb,'["Reconnaissance"]'::jsonb,'Reconnaissance gathers information about authorized targets before deeper testing.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='ethical-hacking-penetration-testing' AND q.title='Final Assessment — Ethical Hacking & Penetration Testing'),'Why is scope important?','single_choice','["It defines what may be tested","It makes passwords stronger","It removes all risk","It replaces authorization"]'::jsonb,'["It defines what may be tested"]'::jsonb,'Scope defines the permitted systems, methods, timing and boundaries of the engagement.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='ethical-hacking-penetration-testing' AND q.title='Final Assessment — Ethical Hacking & Penetration Testing'),'What should a professional report include?','single_choice','["Evidence and remediation guidance","Only a tool list","Unverified rumors","Client passwords"]'::jsonb,'["Evidence and remediation guidance"]'::jsonb,'A useful report provides evidence, impact, reproduction context and practical remediation.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='ethical-hacking-penetration-testing' AND q.title='Final Assessment — Ethical Hacking & Penetration Testing'),'What should a tester do when a test reaches an out-of-scope system?','single_choice','["Stop and follow the rules of engagement","Continue silently","Delete the system","Publish the result"]'::jsonb,'["Stop and follow the rules of engagement"]'::jsonb,'Out-of-scope activity must stop and be handled according to the agreed engagement rules.',1,5),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='network-security-essentials' AND q.title='Final Assessment — Network Security Essentials'),'What is network segmentation used for?','single_choice','["Limit lateral movement and exposure","Increase public access","Disable authentication","Remove logging"]'::jsonb,'["Limit lateral movement and exposure"]'::jsonb,'Segmentation separates trust zones and can limit unnecessary access and lateral movement.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='network-security-essentials' AND q.title='Final Assessment — Network Security Essentials'),'Which protocol is commonly used for secure remote administration?','single_choice','["SSH","FTP","Telnet","HTTP"]'::jsonb,'["SSH"]'::jsonb,'SSH provides encrypted remote administration when correctly configured.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='network-security-essentials' AND q.title='Final Assessment — Network Security Essentials'),'What does a firewall rule control?','single_choice','["Allowed or denied traffic","CPU temperature","Disk formatting","User profile photos"]'::jsonb,'["Allowed or denied traffic"]'::jsonb,'Firewall rules define which traffic is permitted or denied according to policy.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='network-security-essentials' AND q.title='Final Assessment — Network Security Essentials'),'What is an IDS designed to do?','single_choice','["Detect suspicious activity","Encrypt every file","Replace backups","Create user accounts"]'::jsonb,'["Detect suspicious activity"]'::jsonb,'An intrusion detection system monitors for suspicious patterns and generates alerts.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='network-security-essentials' AND q.title='Final Assessment — Network Security Essentials'),'Why are network logs valuable?','single_choice','["They provide investigation evidence","They guarantee prevention","They remove all vulnerabilities","They replace policies"]'::jsonb,'["They provide investigation evidence"]'::jsonb,'Network logs help analysts reconstruct activity and investigate suspicious events.',1,5),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='web-application-security' AND q.title='Final Assessment — Web Application Security'),'What is the safest general approach to SQL query construction?','single_choice','["Parameterized queries","String concatenation","User-controlled SQL","Disabling logs"]'::jsonb,'["Parameterized queries"]'::jsonb,'Parameterized queries separate data from SQL instructions and reduce injection risk.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='web-application-security' AND q.title='Final Assessment — Web Application Security'),'What does authorization determine?','single_choice','["What an authenticated user may access","Whether a cable works","Whether DNS exists","The screen size"]'::jsonb,'["What an authenticated user may access"]'::jsonb,'Authorization controls which resources and actions an authenticated identity is allowed to use.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='web-application-security' AND q.title='Final Assessment — Web Application Security'),'Why should session tokens be protected?','single_choice','["They can represent an authenticated session","They are image files","They replace backups","They are public identifiers"]'::jsonb,'["They can represent an authenticated session"]'::jsonb,'A stolen session token may allow an attacker to act as the victim.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='web-application-security' AND q.title='Final Assessment — Web Application Security'),'What is input validation for?','single_choice','["Constrain unexpected or malicious input","Make every input trusted","Disable HTTPS","Remove authentication"]'::jsonb,'["Constrain unexpected or malicious input"]'::jsonb,'Validation ensures inputs match expected formats and constraints before processing.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='web-application-security' AND q.title='Final Assessment — Web Application Security'),'Why are security headers useful?','single_choice','["They can reduce certain browser attack risks","They replace application authorization","They guarantee zero vulnerabilities","They store passwords"]'::jsonb,'["They can reduce certain browser attack risks"]'::jsonb,'Security headers can instruct browsers to apply additional protections for web content.',1,5),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='python-for-cybersecurity' AND q.title='Final Assessment — Python for Cybersecurity'),'Which Python type is useful for structured key-value data?','single_choice','["dict","tuple","bytes only","None"]'::jsonb,'["dict"]'::jsonb,'Python dictionaries store key-value mappings and are useful for structured security data.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='python-for-cybersecurity' AND q.title='Final Assessment — Python for Cybersecurity'),'Why should API tokens be kept out of source code?','single_choice','["To reduce credential exposure","To improve screen resolution","To increase file size","To disable logs"]'::jsonb,'["To reduce credential exposure"]'::jsonb,'Hard-coded credentials can leak through repositories, logs or shared files.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='python-for-cybersecurity' AND q.title='Final Assessment — Python for Cybersecurity'),'What is exception handling useful for?','single_choice','["Handling expected runtime errors safely","Making code invisible","Deleting evidence","Bypassing authorization"]'::jsonb,'["Handling expected runtime errors safely"]'::jsonb,'Exception handling lets programs fail predictably and report errors without unsafe behavior.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='python-for-cybersecurity' AND q.title='Final Assessment — Python for Cybersecurity'),'Why should automation include rate limits?','single_choice','["To avoid excessive load and unintended impact","To remove authentication","To make passwords public","To skip validation"]'::jsonb,'["To avoid excessive load and unintended impact"]'::jsonb,'Rate limiting reduces accidental overload and helps keep automation controlled.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='python-for-cybersecurity' AND q.title='Final Assessment — Python for Cybersecurity'),'What is a good first step before deploying a security script?','single_choice','["Test it in a controlled environment","Run it against every public host","Disable logging","Remove error handling"]'::jsonb,'["Test it in a controlled environment"]'::jsonb,'Controlled testing helps catch unsafe assumptions before real deployment.',1,5),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='linux-kali-linux-security' AND q.title='Final Assessment — Linux & Kali Linux Security'),'Which Linux mechanism controls file read/write/execute permissions?','single_choice','["File permissions","DNS","TLS","Cookies"]'::jsonb,'["File permissions"]'::jsonb,'Linux file permissions control read, write and execute access for users and groups.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='linux-kali-linux-security' AND q.title='Final Assessment — Linux & Kali Linux Security'),'What is sudo commonly used for?','single_choice','["Controlled elevated privileges","Web browsing","Packet capture only","Password sharing"]'::jsonb,'["Controlled elevated privileges"]'::jsonb,'sudo allows authorized users to execute selected commands with elevated privileges.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='linux-kali-linux-security' AND q.title='Final Assessment — Linux & Kali Linux Security'),'Why use an isolated lab for security tools?','single_choice','["To reduce unintended impact","To make attacks public","To bypass authorization","To disable snapshots"]'::jsonb,'["To reduce unintended impact"]'::jsonb,'Isolation keeps learning and testing away from systems that could be harmed.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='linux-kali-linux-security' AND q.title='Final Assessment — Linux & Kali Linux Security'),'Which service is commonly used for secure remote access?','single_choice','["SSH","Telnet","FTP","HTTP"]'::jsonb,'["SSH"]'::jsonb,'SSH provides encrypted remote administration when correctly configured.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='linux-kali-linux-security' AND q.title='Final Assessment — Linux & Kali Linux Security'),'Why are system logs important during triage?','single_choice','["They help reconstruct events","They guarantee prevention","They replace backups","They expose all passwords"]'::jsonb,'["They help reconstruct events"]'::jsonb,'Logs provide timestamps and activity clues that support incident investigation.',1,5),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='digital-forensics' AND q.title='Final Assessment — Digital Forensics'),'What helps prove evidence was not altered?','single_choice','["Integrity hashing","Changing filenames","Deleting metadata","Editing timestamps"]'::jsonb,'["Integrity hashing"]'::jsonb,'Hashes can be compared to demonstrate that evidence bytes have not changed.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='digital-forensics' AND q.title='Final Assessment — Digital Forensics'),'What is chain of custody?','single_choice','["A record of evidence handling","A password list","A network topology","A backup schedule"]'::jsonb,'["A record of evidence handling"]'::jsonb,'Chain of custody documents who handled evidence, when and for what purpose.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='digital-forensics' AND q.title='Final Assessment — Digital Forensics'),'Why is volatile memory important?','single_choice','["Some evidence can disappear when a system changes state","It never changes","It is always encrypted","It is a backup disk"]'::jsonb,'["Some evidence can disappear when a system changes state"]'::jsonb,'Memory and other volatile artifacts may change or disappear as a system shuts down or processes change.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='digital-forensics' AND q.title='Final Assessment — Digital Forensics'),'What should investigators preserve?','single_choice','["Original evidence and documentation","Only screenshots","Only conclusions","Only tool names"]'::jsonb,'["Original evidence and documentation"]'::jsonb,'Preserving originals and documenting methods supports reliable investigation and later review.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='digital-forensics' AND q.title='Final Assessment — Digital Forensics'),'What makes a forensic report useful?','single_choice','["Reproducible methodology and evidence references","Unverified assumptions","Missing timestamps","No limitations"]'::jsonb,'["Reproducible methodology and evidence references"]'::jsonb,'A good forensic report lets another reviewer understand the methods, evidence and limitations.',1,5),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cloud-security-fundamentals' AND q.title='Final Assessment — Cloud Security Fundamentals'),'What is shared responsibility in cloud security?','single_choice','["Security duties are divided between provider and customer","The provider does everything","The customer does nothing","No one is responsible"]'::jsonb,'["Security duties are divided between provider and customer"]'::jsonb,'Cloud providers and customers each have defined security responsibilities.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cloud-security-fundamentals' AND q.title='Final Assessment — Cloud Security Fundamentals'),'Which control strengthens cloud account access?','single_choice','["MFA","Public credentials","Shared passwords","Anonymous admin"]'::jsonb,'["MFA"]'::jsonb,'MFA adds another verification factor and reduces risk from password compromise.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cloud-security-fundamentals' AND q.title='Final Assessment — Cloud Security Fundamentals'),'Why should cloud storage access be reviewed?','single_choice','["Misconfiguration can expose sensitive data","Storage never has permissions","It changes CPU speed","It disables backups"]'::jsonb,'["Misconfiguration can expose sensitive data"]'::jsonb,'Incorrect storage permissions are a common source of unintended data exposure.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cloud-security-fundamentals' AND q.title='Final Assessment — Cloud Security Fundamentals'),'What does a security group commonly control?','single_choice','["Network traffic to resources","User resumes","Certificate templates","Quiz answers"]'::jsonb,'["Network traffic to resources"]'::jsonb,'Security groups commonly define allowed network traffic for cloud resources.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cloud-security-fundamentals' AND q.title='Final Assessment — Cloud Security Fundamentals'),'Why are cloud audit logs important?','single_choice','["They provide activity evidence","They prevent every attack","They replace IAM","They remove encryption"]'::jsonb,'["They provide activity evidence"]'::jsonb,'Audit logs help reconstruct who did what and when in a cloud environment.',1,5),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='security-operations-threat-analysis' AND q.title='Final Assessment — Security Operations & Threat Analysis'),'What is a SOC?','single_choice','["Security Operations Center","Secure Office Computer","System Output Cache","Service Online Certificate"]'::jsonb,'["Security Operations Center"]'::jsonb,'A SOC is a team or function responsible for monitoring and responding to security events.',1,1),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='security-operations-threat-analysis' AND q.title='Final Assessment — Security Operations & Threat Analysis'),'What is threat intelligence used for?','single_choice','["Contextualizing threats and improving defenses","Sharing passwords","Disabling logs","Replacing authentication"]'::jsonb,'["Contextualizing threats and improving defenses"]'::jsonb,'Threat intelligence provides context that can improve detection, prioritization and response.',1,2),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='security-operations-threat-analysis' AND q.title='Final Assessment — Security Operations & Threat Analysis'),'What is a false positive?','single_choice','["An alert that is not a real security incident","A confirmed breach","A backup","A firewall"]'::jsonb,'["An alert that is not a real security incident"]'::jsonb,'A false positive is an alert that appears suspicious but is not an actual security incident.',1,3),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='security-operations-threat-analysis' AND q.title='Final Assessment — Security Operations & Threat Analysis'),'Why tune detections?','single_choice','["To improve useful signal and reduce noise","To remove all monitoring","To disable alerts","To expose credentials"]'::jsonb,'["To improve useful signal and reduce noise"]'::jsonb,'Detection tuning improves analyst efficiency and reduces unnecessary alert volume.',1,4),
  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='security-operations-threat-analysis' AND q.title='Final Assessment — Security Operations & Threat Analysis'),'What is threat hunting?','single_choice','["Proactively searching for suspicious activity","Waiting for a breach report","Deleting logs","Installing random software"]'::jsonb,'["Proactively searching for suspicious activity"]'::jsonb,'Threat hunting proactively searches for behaviors that may have escaped automated detection.',1,5),
