  ((SELECT q.id FROM public.cwu_quizzes q JOIN public.cwu_courses c ON c.id=q.course_id WHERE c.slug='cybersecurity-career-roadmap' AND q.title='Final Assessment — Cybersecurity Career Roadmap'),'What is a good interview preparation method?','single_choice','["Practice explaining technical decisions","Memorize passwords","Avoid projects","Disable GitHub"]'::jsonb,'["Practice explaining technical decisions"]'::jsonb,'Technical interviews often assess how clearly candidates explain decisions and tradeoffs.',1,4),
