-- CWU seed catalog: 10 published cybersecurity courses with lessons and quizzes.
-- Safe to re-run for courses and lessons using their unique slugs/order.
WITH seed_courses(title,slug,description,category,level,duration_minutes,price_inr) AS (
VALUES
  ('Cybersecurity Fundamentals','cybersecurity-fundamentals','A practical foundation covering core security principles, identity, networks, data protection and incident response.','Cybersecurity','Beginner',300,499),
  ('Ethical Hacking & Penetration Testing','ethical-hacking-penetration-testing','An authorized-testing pathway covering methodology, reconnaissance, validation, exploitation concepts and professional reporting.','Ethical Hacking','Intermediate',360,799),
  ('Network Security Essentials','network-security-essentials','A practical introduction to secure network architecture, protocols, firewalls, monitoring and network incident response.','Networking','Beginner',300,599),
  ('Web Application Security','web-application-security','A structured web-security course covering HTTP, input validation, authentication, authorization, APIs and secure deployment.','Web Development','Intermediate',330,699),
  ('Python for Cybersecurity','python-for-cybersecurity','Hands-on Python concepts for security automation, log analysis, structured data, APIs and defensive utilities.','Programming','Intermediate',300,649),
  ('Linux & Kali Linux Security','linux-kali-linux-security','Linux administration and Kali Linux security learning with permissions, SSH, lab safety, hardening and incident triage.','Linux','Beginner',330,599),
  ('Digital Forensics','digital-forensics','A digital-forensics foundation covering evidence preservation, disk artifacts, memory, browser activity and reporting.','Digital Forensics','Intermediate',360,749),
  ('Cloud Security Fundamentals','cloud-security-fundamentals','Cloud security fundamentals covering shared responsibility, IAM, data protection, network controls and monitoring.','Cloud Security','Intermediate',330,799),
  ('Security Operations & Threat Analysis','security-operations-threat-analysis','An advanced SOC pathway covering threat intelligence, detection engineering, investigations, hunting and security metrics.','Cybersecurity','Advanced',360,899),
  ('Cybersecurity Career Roadmap','cybersecurity-career-roadmap','A practical roadmap for building a cybersecurity portfolio, learning plan, professional profile and early-career strategy.','Career Development','Beginner',240,399)
)
SELECT s.title,s.slug,s.description,s.category,s.level,s.duration_minutes,
       '923e6fb3-6368-4dec-b909-d59e86960aa7'::uuid,s.price_inr,true,false
FROM seed_courses s
ON CONFLICT (slug) DO UPDATE SET
  title=excluded.title, description=excluded.description, category=excluded.category,
  level=excluded.level, duration_minutes=excluded.duration_minutes,
  instructor_id=excluded.instructor_id, price_inr=excluded.price_inr,
  is_published=true, is_archived=false, updated_at=now();

ON CONFLICT (course_id, sort_order) DO UPDATE SET
  title=excluded.title, description=excluded.description, content=excluded.content,
  is_published=true, updated_at=now();

SELECT c.id, NULL, 'Final Assessment — ' || c.title,
       'Five-question assessment covering the core concepts in this course.',900,70,1,true
FROM public.cwu_courses c
WHERE c.slug IN ('cybersecurity-fundamentals','ethical-hacking-penetration-testing','network-security-essentials','web-application-security','python-for-cybersecurity','linux-kali-linux-security','digital-forensics','cloud-security-fundamentals','security-operations-threat-analysis','cybersecurity-career-roadmap')
  AND NOT EXISTS (SELECT 1 FROM public.cwu_quizzes q WHERE q.course_id=c.id AND q.title='Final Assessment — ' || c.title);

ON CONFLICT (quiz_id, sort_order) DO UPDATE SET
  question_text=excluded.question_text, question_type=excluded.question_type,
  options=excluded.options, correct_answers=excluded.correct_answers,
  explanation=excluded.explanation, marks=excluded.marks, updated_at=now();
